<?php

# @autogenerated
declare(strict_types=1);

use DateInterval;
use Jose\Component\Core\JWKSet;
use PHPUnit\Framework\TestCase;
use Civi\Lughauth\Features\Oidc\Authentication\Domain\LogoutToken;
use Civi\Lughauth\Features\Oidc\Key\Domain\Gateway\TokenSigner;

final class LogoutTokenUnitTest extends TestCase
{
    public function test_build_creates_expected_claims(): void
    {
        $signer = new class () implements TokenSigner {
            public ?string $tenant = null;
            public array $data = [];
            public ?DateInterval $expiration = null;

            public function sign(string $tenant, array $data, DateInterval $expiration): string
            {
                $this->tenant = $tenant;
                $this->data = $data;
                $this->expiration = $expiration;
                return 'signed-token';
            }
            public function keysAsJwks(string $tenant): JWKSet
            {
                return new JWKSet([]);
            }
            public function signKeypass(string $tenant, array $data, DateInterval $expiration): string
            {
                return 'keypass-token';
            }
            public function verifyTokenPayload(string $tenant, string $token): ?array
            {
                return null;
            }
            public function verifiedKeypass(string $tenant, string $token): mixed
            {
                return null;
            }
            public function parseSignedPayload(string $tenant, string $token): ?array
            {
                return null;
            }
        };

        $token = LogoutToken::build(
            tenant: 'tenant-one',
            issuer: 'https://issuer.example.com',
            subject: 'user-123',
            clientId: 'client-abc',
            sessionId: 'sid-456',
            signer: $signer
        );

        $this->assertSame('signed-token', $token);
        $this->assertSame('tenant-one', $signer->tenant);
        $this->assertSame('https://issuer.example.com', $signer->data['iss']);
        $this->assertSame('user-123', $signer->data['sub']);
        $this->assertSame('client-abc', $signer->data['aud']);
        $this->assertSame('sid-456', $signer->data['sid']);
        $this->assertArrayHasKey('events', $signer->data);
        $this->assertArrayHasKey('http://schemas.openid.net/event/backchannel-logout', $signer->data['events']);
        $this->assertInstanceOf(stdClass::class, $signer->data['events']['http://schemas.openid.net/event/backchannel-logout']);
        $this->assertArrayNotHasKey('nonce', $signer->data);
        $this->assertSame(5, $signer->expiration?->i);
    }
}
